# Plot each predictor's predicted proportion of Black victims from low to high.

#== paired plot ==
# (Datanovia, 2026b; stefan, 2022)
practical_plot <- ggpubr::ggpaired(
  practical_long,
  x = "group",
  y = "percent_black",
  # (Hervé, 2017)
  id = "id",
  order = c(
    "Low",
    "High"
  ),
  fill = "group",
  color = "group",
  palette = c(
    "Low" = "#9d5e38",
    "High" = "#5e2e11"
  ),
  # (L Tyrone, 2024)
  line.color = NA,
  # (Datanovia, 2026b; stefan, 2022)
  xlab = "Predictor value",
  ylab = "Predicted Black victims (%)"
) +
  # (stefan, 2022; russhh, 2017)
  geom_line(
    aes(
      group = id,
      color = id,
      linetype = id,
      linewidth = id
    )
  ) +
  # (russhh, 2017)
  scale_colour_manual(
    values = c(
      "Relative humidity" = "#275561",
